                    checked: f.id === p.filter,
                    onClick: () => p.onFilter(f.id),
                  }))}
                />
              )}
            </div>
            <button
              className="ib green"
              aria-label="Pesquisar"
              title="Pesquisar"
              onClick={() => {
                if (searching && q) {
                  setQ('');
                  p.onSearch('');
                }
                setSearching((v) => !v);
              }}
