import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { Chat, Message, QuickReply } from '../provider/types';
import { dayLabel, formatPhone } from '../lib/format';
import { Avatar } from './Avatar';
import { chatTitle } from './ChatList';
import { Composer } from './Composer';
import { Icon } from './Icon';
import { Menu } from './Menu';
import { MessageBubble } from './MessageBubble';

interface Props {
  chat: Chat;
  me: string;
  messages: Message[];
  loading: boolean;
  hasMore: boolean;
  error: string;
  quickReplies: QuickReply[];
  onBack: () => void;
  onLoadOlder: () => void;
  onSendText: (text: string, replyTo: Message | null) => Promise<void>;
  onSendFile: (file: File, caption: string, replyTo: Message | null) => Promise<void>;
  onSendVoice: (dataUrl: string, seconds: number) => Promise<void>;
  onReact: (m: Message, emoji: string) => void;
  onDelete: (m: Message) => void;
  onDownload: (m: Message) => Promise<string>;
  onTyping: (s: 'composing' | 'recording') => void;
  onAssign: () => void;
  onTicket: () => void;
  onBot: () => void;
  onInfo: () => void;
  onLabels: () => void;
  onArchive: () => void;
  onPin: () => void;
  onBlock: () => void;
  onDeleteChat: () => void;
}

export function ChatPanel(p: Props) {
  const scroller = useRef<HTMLDivElement>(null);
  const [replyTo, setReplyTo] = useState<Message | null>(null);
  const [menu, setMenu] = useState(false);
  const stick = useRef(true);
  const prevHeight = useRef(0);
  const prevFirst = useRef('');

  const { visible, reactions, byId } = useMemo(() => {
    const byId = new Map<string, Message>();
    const reactions = new Map<string, string[]>();
    const visible: Message[] = [];
    const sorted = [...p.messages].sort((a, b) => a.at - b.at);
    for (const m of sorted) {
      byId.set(m.id, m);
      if (m.kind === 'reaction') {
        if (m.reaction && m.text) reactions.set(m.reaction, [...(reactions.get(m.reaction) || []), m.text]);
        continue;
      }
      visible.push(m);
    }
    return { visible, reactions, byId };
  }, [p.messages]);

  useEffect(() => {
    setReplyTo(null);
    stick.current = true;
  }, [p.chat.id]);

  // Keep the view at the bottom for new messages, and in place when older ones load above.
  useLayoutEffect(() => {
    const el = scroller.current;
    if (!el) return;
    const first = visible[0]?.id || '';
    if (prevFirst.current && first !== prevFirst.current && !stick.current) {
      el.scrollTop += el.scrollHeight - prevHeight.current;
    } else if (stick.current) {
      el.scrollTop = el.scrollHeight;
    }
    prevFirst.current = first;
    prevHeight.current = el.scrollHeight;
  }, [visible]);

  const c = p.chat;
  const lead = c.lead;
  const mine = lead.assignedTo && lead.assignedTo === p.me;
  const botPaused = lead.botPausedUntil > Date.now();
  const sub =
    c.presence === 'composing'
      ? 'Digitando...'
      : c.presence === 'recording'
        ? 'Gravando...'
        : c.isGroup
          ? 'Grupo'
          : formatPhone(c.phone);

  let lastDay = '';

  return (
    <section className="chat">
      <header className="chat-head blur">
        <button className="ib grey back" aria-label="Voltar" onClick={p.onBack}>
          <Icon name="back" />
        </button>
        <button className="ch-who" onClick={p.onInfo}>
          <Avatar src={c.image} group={c.isGroup} size={40} />
          <span>
            <strong>{chatTitle(c)}</strong>
            <small className={c.presence ? 'typing' : ''}>{sub}</small>
          </span>
        </button>
        <div className="ch-actions">
          <button
            className={'pill' + (mine ? ' on' : lead.assignedTo ? ' other' : '')}
            onClick={p.onAssign}
            title={mine ? 'Remover atribuição' : 'Atribuir à mim'}
          >
            <Icon name="person" size={18} />
            <span>{mine ? 'Comigo' : lead.assignedTo ? lead.assignedTo : 'Atribuir à mim'}</span>
          </button>
          <button
            className={'pill' + (lead.ticketOpen ? ' warn' : '')}
            onClick={p.onTicket}
            title={lead.ticketOpen ? 'Marcar como concluído' : 'Abrir atendimento'}
          >
            <Icon name={lead.ticketOpen ? 'unlock' : 'lock'} size={18} />
            <span>{lead.ticketOpen ? 'Em aberto' : 'Fechado'}</span>
          </button>
          <button
            className={'pill' + (botPaused ? ' off' : ' bot')}
            onClick={p.onBot}
            title={botPaused ? 'Reativar o robô' : 'Pausar o robô nesta conversa'}
          >
            <Icon name="robot" size={18} />
            <span>{botPaused ? 'Robô pausado' : 'Robô ativo'}</span>
          </button>
          <button className="ib grey" aria-label="Etiquetar" title="Etiquetas" onClick={p.onLabels}>
            <Icon name="label" />
          </button>
          <button className="ib grey" aria-label="Dados do contato" title="Dados do contato" onClick={p.onInfo}>
            <Icon name="info" />
          </button>
          <div className="rel">
            <button className="ib grey" aria-label="Mais opções" onClick={() => setMenu((v) => !v)}>
              <Icon name="more" />
            </button>
            {menu && (
              <Menu
                onClose={() => setMenu(false)}
                items={[
                  { label: mine ? 'Remover atribuição' : 'Atribuir à mim', icon: 'person', onClick: p.onAssign },
                  { label: lead.ticketOpen ? 'Marcar como concluído' : 'Abrir atendimento', icon: 'ok', onClick: p.onTicket },
                  { label: botPaused ? 'Reativar robô' : 'Pausar robô', icon: 'robot', onClick: p.onBot },
                  { label: 'Etiquetar', icon: 'label', onClick: p.onLabels },
                  { label: c.pinned ? 'Desafixar Chat' : 'Fixar Chat', icon: 'pin', onClick: p.onPin },
                  { label: c.archived ? 'Desarquivar conversa' : 'Arquivar conversa', icon: 'archive', onClick: p.onArchive },
                  ...(c.isGroup
                    ? []
                    : [{ label: c.blocked ? 'Desbloquear contato' : 'Bloquear contato', icon: 'block', onClick: p.onBlock }]),
                  { label: 'Apagar chat', icon: 'trash', danger: true, onClick: p.onDeleteChat },
                ]}
              />
            )}
          </div>
        </div>
      </header>

      <div
        className="msgs"
        ref={scroller}
        onScroll={(e) => {
          const el = e.currentTarget;
          stick.current = el.scrollTop + el.clientHeight > el.scrollHeight - 80;
          if (el.scrollTop < 120 && p.hasMore && !p.loading) {
            prevHeight.current = el.scrollHeight;
            p.onLoadOlder();
          }
        }}
      >
        <div className="msgs-inner">
          {p.hasMore && (
            <button className="older" onClick={p.onLoadOlder} disabled={p.loading}>
              {p.loading ? 'Carregando…' : 'Carregar mensagens anteriores'}
            </button>
          )}
          {p.error && <div className="sys err">{p.error}</div>}
          {!p.loading && !p.error && visible.length === 0 && <div className="sys">Nenhuma mensagem ainda.</div>}
          {visible.map((m) => {
            const d = dayLabel(m.at);
            const sep = d !== lastDay;
            lastDay = d;
            return (
              <div key={m.id}>
                {sep && <div className="day">{d}</div>}
                <MessageBubble
                  m={m}
                  quoted={m.quotedId ? byId.get(m.quotedId) : undefined}
                  reactions={reactions.get(m.id) || []}
                  showSender={c.isGroup}
                  onReply={setReplyTo}
                  onReact={p.onReact}
                  onDelete={p.onDelete}
                  onDownload={p.onDownload}
                />
              </div>
            );
          })}
        </div>
      </div>

      <Composer
        disabled={c.blocked ? 'Contato bloqueado. Desbloqueie para enviar mensagens.' : undefined}
        replyTo={replyTo}
        quickReplies={p.quickReplies}
        onCancelReply={() => setReplyTo(null)}
        onSendText={async (t) => {
          const r = replyTo;
          setReplyTo(null);
          stick.current = true;
          await p.onSendText(t, r);
        }}
        onSendFile={async (f, cap) => {
          const r = replyTo;
          setReplyTo(null);
          stick.current = true;
          await p.onSendFile(f, cap, r);
        }}
        onSendVoice={async (u, s) => {
          stick.current = true;
          await p.onSendVoice(u, s);
        }}
        onTyping={p.onTyping}
      />
    </section>
  );
}

import { useEffect, useState } from 'react';
import type { Chat, Label } from '../provider/types';
import { formatPhone } from '../lib/format';
import { Avatar } from './Avatar';
import { chatTitle } from './ChatList';
import { Icon } from './Icon';

interface Props {
  chat: Chat;
  labels: Label[];
  me: string;
  onClose: () => void;
  onSave: (fields: Record<string, unknown>) => Promise<void>;
  onLabels: () => void;
}

/** Contact / lead details saved on the chat itself in UAZAPI (lead_* fields). */
export function LeadPanel({ chat, labels, me, onClose, onSave, onLabels }: Props) {
  const l = chat.lead;
  const [form, setForm] = useState({
    lead_name: l.name,
    lead_fullName: l.fullName,
    lead_email: l.email,
    lead_personalid: l.personalId,
    lead_status: l.status,
    lead_notes: l.notes,
    lead_tags: l.tags.join(', '),
  });
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState('');

  useEffect(() => {
    setForm({
      lead_name: l.name,
      lead_fullName: l.fullName,
      lead_email: l.email,
      lead_personalid: l.personalId,
      lead_status: l.status,
      lead_notes: l.notes,
      lead_tags: l.tags.join(', '),
    });
    setMsg('');
  }, [chat.id]); // eslint-disable-line react-hooks/exhaustive-deps

  const set = (k: keyof typeof form) => (e: { target: { value: string } }) =>
    setForm((f) => ({ ...f, [k]: e.target.value }));

  async function save() {
    setBusy(true);
    setMsg('');
    try {
      await onSave({
        ...form,
        lead_tags: form.lead_tags
          .split(',')
          .map((t) => t.trim())
          .filter(Boolean),
      });
      setMsg('Atualizado');
    } catch (e) {
      setMsg((e as Error).message || 'Erro ao salvar');
    } finally {
      setBusy(false);
    }
  }

  const chatLabels = labels.filter((x) => chat.labels.includes(x.id));

  return (
    <aside className="lead">
      <header className="lead-head blur">
        <button className="ib grey" aria-label="Fechar" onClick={onClose}>
          <Icon name="close" />
        </button>
        <span>Dados do contato</span>
      </header>
      <div className="lead-body">
        <div className="lead-id">
          <Avatar src={chat.image} group={chat.isGroup} size={120} />
          <strong>{chatTitle(chat)}</strong>
          {!chat.isGroup && <span>{formatPhone(chat.phone)}</span>}
        </div>

        <div className="lead-card">
          <div className="lead-row">
            <span>Atendimento está </span>
            <b className={l.ticketOpen ? 'red' : 'blue'}>{l.ticketOpen ? 'aberto' : 'fechado'}</b>
          </div>
          <div className="lead-row">
            <span>Contato atribuído à</span>
            <b>{l.assignedTo ? (l.assignedTo === me ? 'mim' : l.assignedTo) : 'Ninguém'}</b>
          </div>
          {l.botPausedUntil > Date.now() && (
            <div className="lead-row">
              <span>Robô pausado até</span>
              <b>{new Date(l.botPausedUntil).toLocaleString('pt-BR')}</b>
            </div>
          )}
        </div>

        <div className="lead-card">
          <div className="lead-label-head">
            <span>Etiquetas</span>
            <button className="link" onClick={onLabels}>
              <Icon name="label" size={16} /> Etiquetar
            </button>
          </div>
          <div className="chips">
            {chatLabels.length === 0 && <span className="muted small">Sem etiquetas</span>}
            {chatLabels.map((x) => (
              <span key={x.id} className="chip" style={{ background: x.color + '33', color: '#111b21' }}>
                <i style={{ background: x.color }} />
                {x.name}
              </span>
            ))}
          </div>
        </div>

        <div className="lead-card form">
          <label>
            Nome
            <input value={form.lead_name} onChange={set('lead_name')} />
          </label>
          <label>
            Nome completo
            <input value={form.lead_fullName} onChange={set('lead_fullName')} />
          </label>
          <label>
            E-mail
            <input type="email" value={form.lead_email} onChange={set('lead_email')} />
          </label>
          <label>
            CPF
            <input value={form.lead_personalid} onChange={set('lead_personalid')} />
          </label>
          <label>
            Status
            <input value={form.lead_status} onChange={set('lead_status')} />
          </label>
          <label>
            Tags
            <input
              placeholder="assinante, testando, quente, frio, como preferir"
              value={form.lead_tags}
              onChange={set('lead_tags')}
            />
          </label>
          <label>
            Notas
            <textarea rows={4} value={form.lead_notes} onChange={set('lead_notes')} />
          </label>
          <div className="lead-save">
            {msg && <span className="muted small">{msg}</span>}
            <button className="btn-primary" onClick={save} disabled={busy}>
              {busy ? 'Salvando…' : 'Salvar'}
            </button>
          </div>
        </div>
      </div>
    </aside>
  );
}

