import { useEffect, useRef, useState } from 'react';
import type { Message, QuickReply } from '../provider/types';
import { VoiceRecorder } from '../lib/audio';
import { duration } from '../lib/format';
import { Icon } from './Icon';

interface Props {
  disabled?: string;
  replyTo: Message | null;
  quickReplies: QuickReply[];
  onCancelReply: () => void;
  onSendText: (text: string) => Promise<void>;
  onSendFile: (file: File, caption: string) => Promise<void>;
  onSendVoice: (dataUrl: string, seconds: number) => Promise<void>;
  onTyping: (state: 'composing' | 'recording') => void;
}

const MAX_BYTES = 16 * 1024 * 1024;

export function Composer(p: Props) {
  const [text, setText] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [recording, setRecording] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [error, setError] = useState('');
  const [qrIndex, setQrIndex] = useState(0);
  const rec = useRef<VoiceRecorder | null>(null);
  const area = useRef<HTMLTextAreaElement>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const lastTyping = useRef(0);

  const qrQuery = text.startsWith('/') && !text.includes('\n') ? text.slice(1).toLowerCase() : null;
  const qrMatches =
    qrQuery === null
      ? []
      : p.quickReplies.filter(
          (q) => q.shortCut.toLowerCase().includes(qrQuery) || q.text.toLowerCase().includes(qrQuery),
        ).slice(0, 8);

  useEffect(() => {
    if (!recording) return;
    const t = setInterval(() => setElapsed(Math.round((Date.now() - (rec.current?.startedAt || Date.now())) / 1000)), 500);
    return () => clearInterval(t);
  }, [recording]);

  useEffect(() => {
    const el = area.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = Math.min(el.scrollHeight, 140) + 'px';
  }, [text]);

  useEffect(() => {
    if (p.replyTo) area.current?.focus();
  }, [p.replyTo]);

  async function send() {
    setError('');
    try {
      if (file) {
        const f = file;
        const cap = text.trim();
        setFile(null);
        setText('');
        await p.onSendFile(f, cap);
        return;
      }
      const t = text.trim();
      if (!t) return;
      setText('');
      await p.onSendText(t);
    } catch (e) {
      setError((e as Error).message || 'Não foi possível enviar.');
    }
  }

  async function toggleRecord() {
    setError('');
    if (!recording) {
      try {
        rec.current = new VoiceRecorder();
        await rec.current.start();
        setElapsed(0);
        setRecording(true);
        p.onTyping('recording');
      } catch {
        setError('Permita o uso do microfone para gravar áudio.');
      }
      return;
    }
    setRecording(false);
    try {
      const { dataUrl, seconds } = await rec.current!.stop();
      await p.onSendVoice(dataUrl, seconds);
    } catch (e) {
      setError((e as Error).message || 'Não foi possível enviar o áudio.');
    }
  }

  if (p.disabled) return <div className="composer-off">{p.disabled}</div>;

  return (
    <div className="composer-wrap">
      {qrMatches.length > 0 && (
        <div className="qr-pop" role="listbox" aria-label="Respostas Rápidas">
          {qrMatches.map((q, i) => (
            <button
              key={q.id || i}
              className={i === qrIndex ? 'on' : ''}
              onMouseEnter={() => setQrIndex(i)}
              onClick={() => {
                setText(q.text);
                area.current?.focus();
              }}
            >
              <strong>/{q.shortCut}</strong>
              <span>{q.text}</span>
            </button>
          ))}
        </div>
      )}
      {p.replyTo && (
        <div className="reply-bar">
          <div>
            <span>Respondendo {p.replyTo.fromMe ? 'você' : p.replyTo.senderName || 'contato'}</span>
            <p>{p.replyTo.text || p.replyTo.fileName || 'Mídia'}</p>
          </div>
          <button className="ib grey" aria-label="Cancelar resposta" onClick={p.onCancelReply}>
            <Icon name="close" size={20} />
          </button>
        </div>
      )}
      {file && (
        <div className="file-bar">
          <Icon name={file.type.startsWith('image/') ? 'camera' : file.type.startsWith('video/') ? 'video' : 'doc'} size={22} />
          <span>{file.name}</span>
          <button className="ib grey" aria-label="Remover arquivo" onClick={() => setFile(null)}>
            <Icon name="close" size={20} />
          </button>
        </div>
      )}
      {error && <div className="composer-err">{error}</div>}
      <div className="composer">
        {recording ? (
          <>
            <button
              className="ib grey"
              aria-label="Cancelar gravação"
              onClick={() => {
                rec.current?.cancel();
                setRecording(false);
              }}
            >
              <Icon name="trash" />
            </button>
            <div className="rec-live">
              <span className="rec-dot" /> Gravando... {duration(elapsed) || '0:00'}
            </div>
          </>
        ) : (
          <>
            <button className="ib grey" aria-label="Anexar arquivo" title="Documento ou Mídia" onClick={() => fileInput.current?.click()}>
              <Icon name="attach" />
            </button>
            <input
              ref={fileInput}
              type="file"
              hidden
              onChange={(e) => {
                const f = e.target.files?.[0];
                e.target.value = '';
                if (!f) return;
                if (f.size > MAX_BYTES) {
                  setError('Arquivo maior que 16 MB.');
                  return;
                }
                setFile(f);
              }}
            />
            <textarea
              ref={area}
              rows={1}
              placeholder={file ? 'Legenda (opcional)' : 'Mensagem  ( / para respostas rápidas)'}
              value={text}
              onChange={(e) => {
                setText(e.target.value);
                setQrIndex(0);
                if (Date.now() - lastTyping.current > 4000) {
                  lastTyping.current = Date.now();
                  p.onTyping('composing');
                }
              }}
              onKeyDown={(e) => {
                if (qrMatches.length) {
                  if (e.key === 'ArrowDown') return e.preventDefault(), setQrIndex((i) => (i + 1) % qrMatches.length);
                  if (e.key === 'ArrowUp')
                    return e.preventDefault(), setQrIndex((i) => (i - 1 + qrMatches.length) % qrMatches.length);
                  if (e.key === 'Enter' || e.key === 'Tab') {
                    e.preventDefault();
                    setText(qrMatches[qrIndex]?.text || text);
                    return;
                  }
                }
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  send();
                }
              }}
            />
          </>
        )}
        {text.trim() || file ? (
          <button className="ib send" aria-label="Enviar" onClick={send}>
            <Icon name="send" />
          </button>
        ) : (
          <button className={'ib ' + (recording ? 'send' : 'grey')} aria-label={recording ? 'Enviar áudio' : 'Gravar áudio'} onClick={toggleRecord}>
            <Icon name={recording ? 'send' : 'mic'} />
          </button>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import type { Message } from '../provider/types';
import { duration, richText, timeOf } from '../lib/format';
import { Icon } from './Icon';

interface Props {
  m: Message;
  quoted?: Message;
  reactions: string[];
  showSender: boolean;
  onReply: (m: Message) => void;
  onReact: (m: Message, emoji: string) => void;
  onDelete: (m: Message) => void;
  onDownload: (m: Message) => Promise<string>;
}

const QUICK = ['👍', '❤️', '😂', '😮', '😢', '🙏'];

function Ticks({ m }: { m: Message }) {
  if (m.failed) return <span className="tick fail" title="Não enviada">!</span>;
  if (m.pending) return <Icon name="clock" size={14} className="tick" />;
  const s = m.status.toLowerCase();
  if (s.includes('read') || s.includes('play')) return <Icon name="checks" size={16} className="tick read" />;
  if (s.includes('deliver')) return <Icon name="checks" size={16} className="tick" />;
  return <Icon name="check" size={16} className="tick" />;
}

function quotedText(q?: Message) {
  if (!q) return 'Mensagem';
  if (q.text) return q.text;
  return { image: 'Foto', video: 'Vídeo', audio: 'Áudio', document: q.fileName || 'Documento', sticker: 'Figurinha' }[
    q.kind as string
  ] || 'Mensagem';
}

export function MessageBubble({ m, quoted, reactions, showSender, onReply, onReact, onDelete, onDownload }: Props) {
  const [url, setUrl] = useState(m.fileUrl);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState('');
  const [tools, setTools] = useState(false);

  async function fetchFile() {
    if (url || loading) return url;
    setLoading(true);
    setErr('');
    try {
      const u = await onDownload(m);
      setUrl(u);
      return u;
    } catch (e) {
      setErr('Não foi possível baixar.');
      return '';
    } finally {
      setLoading(false);
    }
  }

  const caption = m.kind === 'text' ? '' : m.text || m.caption;
  let body: JSX.Element | null = null;

  switch (m.kind) {
    case 'image':
    case 'sticker':
      body = url ? (
        <a href={url} target="_blank" rel="noreferrer">
          <img className={m.kind === 'sticker' ? 'sticker' : 'media-img'} src={url} alt={caption || 'Imagem'} />
        </a>
      ) : (
        <button className="media-load" onClick={fetchFile}>
          {m.thumb ? <img src={m.thumb} alt="" className="media-img blurred" /> : <span className="media-ph" />}
          <span className="media-btn">
            <Icon name="download" size={20} /> {loading ? 'Baixando…' : 'Ver imagem'}
          </span>
        </button>
      );
      break;
    case 'video':
      body = url ? (
        <video className="media-img" src={url} controls preload="metadata" />
      ) : (
        <button className="media-load" onClick={fetchFile}>
          {m.thumb ? <img src={m.thumb} alt="" className="media-img blurred" /> : <span className="media-ph" />}
          <span className="media-btn">
            <Icon name="play" size={20} /> {loading ? 'Baixando…' : 'Ver vídeo'}
          </span>
        </button>
      );
      break;
    case 'audio':
      body = url ? (
        <audio className="audio" src={url} controls preload="metadata" />
      ) : (
        <button className="audio-load" onClick={fetchFile}>
          <Icon name="play" size={22} />
          <span className="audio-bar" />
          <span className="audio-len">{loading ? '…' : duration(m.seconds) || 'Áudio'}</span>
        </button>
      );
      break;
    case 'document':
      body = (
        <button
          className="doc"
          onClick={async () => {
            const u = await fetchFile();
            if (u) window.open(u, '_blank', 'noopener');
          }}
        >
          <Icon name="doc" size={28} />
          <span className="doc-name">{m.fileName || 'Documento'}</span>
          <Icon name="download" size={20} />
        </button>
      );
      break;
    case 'location':
      body = (
        <a
          className="doc"
          target="_blank"
          rel="noreferrer"
          href={m.lat !== undefined ? `https://maps.google.com/?q=${m.lat},${m.lng}` : '#'}
        >
          <Icon name="place" size={28} />
          <span className="doc-name">Localização</span>
        </a>
      );
      break;
    case 'deleted':
      body = <em className="muted">Mensagem apagada</em>;
      break;
    case 'contact':
      body = (
        <div className="doc">
          <Icon name="person" size={28} />
          <span className="doc-name">{m.fileName || m.text || 'Contato'}</span>
        </div>
      );
      break;
    case 'poll':
      body = <div className="poll">📊 {m.text || 'Enquete'}</div>;
      break;
    default:
      body = null;
  }

  const text = m.kind === 'text' || m.kind === 'other' ? m.edited || m.text : caption;

  return (
    <div className={'msg-row ' + (m.fromMe ? 'out' : 'in')}>
      <div className={'bubble' + (m.kind === 'sticker' ? ' bare' : '')} onMouseLeave={() => setTools(false)}>
        {showSender && !m.fromMe && m.senderName && <div className="sender">{m.senderName}</div>}
        {m.quotedId && (
          <div className="quoted">
            <span>{quoted ? (quoted.fromMe ? 'Você' : quoted.senderName || 'Contato') : 'Resposta'}</span>
            <p>{quotedText(quoted)}</p>
          </div>
        )}
        {body}
        {err && <div className="muted small">{err}</div>}
        {text && <div className="text">{richText(text)}</div>}
        <div className="meta">
          {m.edited && <span>Editada</span>}
          <span>{timeOf(m.at)}</span>
          {m.fromMe && <Ticks m={m} />}
        </div>
        {reactions.length > 0 && <div className="reacts">{reactions.join('')}</div>}
        {!m.pending && m.kind !== 'deleted' && (
          <button className="msg-tools-btn" aria-label="Opções da mensagem" onClick={() => setTools((v) => !v)}>
            ▾
          </button>
        )}
        {tools && (
          <div className="msg-tools">
            <div className="emoji-row">
              {QUICK.map((e) => (
                <button key={e} onClick={() => (setTools(false), onReact(m, e))}>
                  {e}
                </button>
              ))}
            </div>
            <button onClick={() => (setTools(false), onReply(m))}>
              <Icon name="reply" size={18} /> Responder
            </button>
            {m.fromMe && (
              <button className="danger" onClick={() => (setTools(false), onDelete(m))}>
                <Icon name="trash" size={18} /> Apagar mensagem
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

